{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.inventory_health_final AS WITH warehouse_base_raw AS ( SELECT CASE WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'SN%\' OR UPPER(TRIM(\"Item SkuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item SkuCode\")) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(\"Item SkuCode\")) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\"::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(\"Item SkuCode\")) END END AS sku_group, UPPER(TRIM(facility)) AS facility, inventory, \"Bad Inventory\" AS bad_inv, \"Inventory Blocked\" AS blocked_inv, \"Inventory Not Synced\" AS inv_not_synced, \"Stock In Transfer\" AS stock_in_transfer, \"Not Found\" AS stock_not_found, \"Open Sale\" AS open_sale, \"Open Purchase\" AS open_purchase, UPPER(TRIM(REGEXP_SUBSTR(\"Item SkuCode\", \'[^-]+$\'))) AS size_token FROM snitch_db.maplemonk.unicommerce_live_inventory ), warehouse_base AS ( SELECT sku_group, SUM(CASE WHEN size_token IN (\'XS\', \'28\') THEN inventory ELSE 0 END) AS XS, SUM(CASE WHEN size_token IN (\'S\', \'30\') THEN inventory ELSE 0 END) AS S, SUM(CASE WHEN size_token IN (\'M\', \'32\') THEN inventory ELSE 0 END) AS M, SUM(CASE WHEN size_token IN (\'L\', \'34\') THEN inventory ELSE 0 END) AS L, SUM(CASE WHEN size_token IN (\'XL\', \'36\') THEN inventory ELSE 0 END) AS XL, SUM(CASE WHEN size_token IN (\'2XL\', \'XXL\', \'38\') THEN inventory ELSE 0 END) AS \"2XL\", SUM(CASE WHEN size_token IN (\'3XL\', \'XXXL\', \'40\') THEN inventory ELSE 0 END) AS \"3XL\", SUM(CASE WHEN size_token IN (\'4XL\', \'42\') THEN inventory ELSE 0 END) AS \"4XL\", SUM(CASE WHEN size_token IN (\'5XL\', \'44\') THEN inventory ELSE 0 END) AS \"5XL\", SUM(CASE WHEN size_token IN (\'6XL\', \'46\') THEN inventory ELSE 0 END) AS \"6XL\", SUM(CASE WHEN size_token IN (\'7XL\', \'48\') THEN inventory ELSE 0 END) AS \"7XL\", SUM(CASE WHEN size_token IN (\'8XL\', \'50\') THEN inventory ELSE 0 END) AS \"8XL\", SUM(CASE WHEN facility = \'SAPL-NORTH-TAURU\' THEN inventory ELSE 0 END) AS north_warehouse, SUM(CASE WHEN facility IN (\'SAPL-WH1\',\'SAPL-WH2\') THEN inventory ELSE 0 END) AS south_warehouse, SUM(inventory) AS inventory, SUM(COALESCE(bad_inv,0)) AS bad_inv, SUM(COALESCE(blocked_inv,0)) AS blocked_inv, SUM(COALESCE(inv_not_synced,0)) AS inv_not_synced, SUM(COALESCE(stock_in_transfer,0)) AS stock_in_transfer, SUM(COALESCE(stock_not_found,0)) AS stock_not_found, SUM(COALESCE(open_sale,0)) AS open_sale, SUM(COALESCE(open_purchase,0)) AS open_purchase FROM warehouse_base_raw GROUP BY 1 ), meta_data AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, UPPER(TRIM(l1_category)) AS l1_category, CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%SFS%\' THEN \'SHIRTS\' WHEN UPPER(TRIM(category)) = \'OVERSHIRT\' THEN \'OVERSHIRTS\' ELSE UPPER(TRIM(category)) END AS category, UPPER(meta1) AS meta1, UPPER(meta2) AS meta2, UPPER(meta3) AS meta3 FROM snitch_db.maplemonk.meta_mapping_cogs_sku WHERE LOWER(TRIM(category)) NOT IN (\'(nil)\',\'default\',\'innerwear\') ), ageing AS ( SELECT CASE WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'SN%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'BP%\' THEN UPPER(TRIM(\"Item Type skuCode\")) WHEN UPPER(TRIM(\"Item Type skuCode\")) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+-[^-]+\'))) ELSE UPPER(TRIM(COALESCE( REGEXP_SUBSTR(\"Item Type skuCode\"::STRING,\'^[^-]+-[^-]+\',1,1), \"Item Type skuCode\"::STRING ))) END AS sku_group, MIN(putaway_completed_date) AS start_date, CURRENT_DATE() - MIN(putaway_completed_date) AS ageing FROM snitch_db.maplemonk.putaway_tracking GROUP BY 1 ), eoss_bf AS ( SELECT UPPER(TRIM(sku_group)) AS sku_group, MAX(CASE WHEN UPPER(TRIM(eoss)) = \'EOSS\' THEN 1 ELSE 0 END) AS eoss, MAX(CASE WHEN UPPER(TRIM(bf)) = \'BF\' THEN 1 ELSE 0 END) AS bf FROM snitch_db.maplemonk.eoss_bf WHERE sku_group IS NOT NULL GROUP BY 1 ), warehouse_sales AS ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, SUM(CASE WHEN UPPER(TRIM(type)) = \'STORE\' THEN gross_quantity ELSE 0 END) AS offline_sales_qty, SUM(CASE WHEN UPPER(TRIM(type)) = \'MARKETPLACE\' THEN gross_quantity ELSE 0 END) AS mp_sales_qty, SUM(CASE WHEN UPPER(TRIM(type)) NOT IN (\'STORE\',\'MARKETPLACE\') THEN gross_quantity ELSE 0 END) AS shopify_sales_qty, SUM(CASE WHEN UPPER(TRIM(type)) = \'STORE\' THEN gross_sales ELSE 0 END) AS offline_sales_value, SUM(CASE WHEN UPPER(TRIM(type)) = \'MARKETPLACE\' THEN gross_sales ELSE 0 END) AS mp_sales_value, SUM(CASE WHEN UPPER(TRIM(type)) NOT IN (\'STORE\',\'MARKETPLACE\') THEN gross_sales ELSE 0 END) AS shopify_sales_value, SUM(CASE WHEN date >= CURRENT_DATE - 30 THEN gross_quantity ELSE 0 END) / 30.0 AS total_ros_l30, SUM(CASE WHEN UPPER(TRIM(type)) = \'STORE\' AND date >= CURRENT_DATE - 30 THEN gross_quantity ELSE 0 END) / 30.0 AS offline_ros_l30, SUM(CASE WHEN UPPER(TRIM(type)) = \'MARKETPLACE\' AND date >= CURRENT_DATE - 30 THEN gross_quantity ELSE 0 END) / 30.0 AS mp_ros_l30, SUM(CASE WHEN UPPER(TRIM(type)) NOT IN (\'STORE\',\'MARKETPLACE\') AND date >= CURRENT_DATE - 30 THEN gross_quantity ELSE 0 END) / 30.0 AS shopify_ros_l30 FROM snitch_db.maplemonk.horizontal_sales_categories GROUP BY 1 ), warehouse_final_base AS ( SELECT b.sku_group, md.l1_category, md.category, md.meta1, md.meta2, md.meta3, a.ageing, b.inventory, b.north_warehouse, b.south_warehouse, b.XS, b.S, b.M, b.L, b.XL, b.\"2XL\", b.\"3XL\", b.\"4XL\", b.\"5XL\", b.\"6XL\", b.\"7XL\", b.\"8XL\", eb.eoss, eb.bf, s.shopify_sales_qty, s.mp_sales_qty, s.offline_sales_qty, s.shopify_sales_value, s.mp_sales_value, s.offline_sales_value, s.total_ros_l30, s.mp_ros_l30, s.offline_ros_l30, s.shopify_ros_l30, b.bad_inv, b.blocked_inv, b.inv_not_synced, b.stock_in_transfer, b.stock_not_found, b.open_sale, b.open_purchase FROM warehouse_base b LEFT JOIN meta_data md ON b.sku_group = md.sku_group LEFT JOIN ageing a ON b.sku_group = a.sku_group LEFT JOIN warehouse_sales s ON b.sku_group = s.sku_group LEFT JOIN eoss_bf eb ON b.sku_group = eb.sku_group ), warehouse_calc AS ( SELECT a.*, CASE WHEN a.sku_group LIKE \'%4MBG%\' THEN GREATEST( LEAST( ROUND((COALESCE(a.\"3XL\",0) - 1) / 3), ROUND((COALESCE(a.\"4XL\",0) - 1) / 3), ROUND((COALESCE(a.\"5XL\",0) - 1) / 2), ROUND((COALESCE(a.\"6XL\",0) - 1) / 2) ), 0 ) ELSE GREATEST( LEAST( ROUND((COALESCE(a.S,0) - 2) / 2), ROUND((COALESCE(a.M,0) - 2) / 4), ROUND((COALESCE(a.L,0) - 2) / 4), ROUND((COALESCE(a.XL,0) - 2) / 2) ), 0 ) END AS full_size_options FROM warehouse_final_base a ), store_base AS ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, marketplace_mapped AS store_name, inventory, xs_units AS XS, s_units AS S, m_units AS M, l_units AS L, xl_units AS XL, xxl_units AS \"2XL\", xl3_units AS \"3XL\", xl4_units AS \"4XL\", xl5_units AS \"5XL\", xl6_units AS \"6XL\", NULL AS \"7XL\", NULL AS \"8XL\", total_sales AS sales, ROUND(sales_last_30_days / 30, 2) AS ros_l30, days_since_first_order AS ageing FROM snitch_db.maplemonk.offline_master WHERE sku_group IS NOT NULL ), price AS ( SELECT DISTINCT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'SH%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) WHEN UPPER(TRIM(sku_group)) LIKE \'4C%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, MAX(price) AS price FROM snitch_db.maplemonk.horizontal_sales_categories WHERE sku_group IS NOT NULL GROUP BY 1 ), store_channel_ros AS ( SELECT CASE WHEN UPPER(TRIM(sku_group)) LIKE \'SN%\' OR UPPER(TRIM(sku_group)) LIKE \'BP%\' THEN UPPER(TRIM(sku_group)) WHEN UPPER(TRIM(sku_group)) LIKE \'MP%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+-[^-]+\'))) ELSE CASE WHEN UPPER(TRIM(sku_group)) LIKE \'%-%\' THEN UPPER(TRIM(REGEXP_SUBSTR(sku_group::STRING, \'^[^-]+-[^-]+\'))) ELSE UPPER(TRIM(sku_group)) END END AS sku_group, SUM(CASE WHEN UPPER(TRIM(type)) = \'STORE\' AND date >= CURRENT_DATE - 30 THEN gross_quantity ELSE 0 END) / 30.0 AS offline_ros_l30, SUM(CASE WHEN UPPER(TRIM(type)) = \'MARKETPLACE\' AND date >= CURRENT_DATE - 30 THEN gross_quantity ELSE 0 END) / 30.0 AS mp_ros_l30, SUM(CASE WHEN UPPER(TRIM(type)) NOT IN (\'STORE\',\'MARKETPLACE\') AND date >= CURRENT_DATE - 30 THEN gross_quantity ELSE 0 END) / 30.0 AS shopify_ros_l30 FROM snitch_db.maplemonk.horizontal_sales_categories WHERE sku_group IS NOT NULL GROUP BY 1 ), store_final_calc AS ( SELECT b.sku_group, b.store_name, md.l1_category, md.category, md.meta1, md.meta2, md.meta3, eb.eoss, eb.bf, b.inventory, b.XS, b.S, b.M, b.L, b.XL, b.\"2XL\", b.\"3XL\", b.\"4XL\", b.\"5XL\", b.\"6XL\", b.\"7XL\", b.\"8XL\", CASE WHEN b.sku_group LIKE \'%4MBG%\' THEN GREATEST( LEAST( ROUND((COALESCE(b.\"3XL\",0) - 1) / 3), ROUND((COALESCE(b.\"4XL\",0) - 1) / 3), ROUND((COALESCE(b.\"5XL\",0) - 1) / 2), ROUND((COALESCE(b.\"6XL\",0) - 1) / 2) ), 0 ) ELSE GREATEST( LEAST( ROUND((COALESCE(b.S,0) - 2) / 2), ROUND((COALESCE(b.M,0) - 2) / 4), ROUND((COALESCE(b.L,0) - 2) / 4), ROUND((COALESCE(b.XL,0) - 2) / 2) ), 0 ) END AS full_size_options, b.ros_l30, scr.mp_ros_l30, scr.shopify_ros_l30, scr.offline_ros_l30, p.price, b.sales, b.ageing FROM store_base b LEFT JOIN meta_data md ON md.sku_group = b.sku_group LEFT JOIN eoss_bf eb ON b.sku_group = eb.sku_group LEFT JOIN price p ON b.sku_group = p.sku_group LEFT JOIN store_channel_ros scr ON b.sku_group = scr.sku_group WHERE b.sku_group IS NOT NULL ) SELECT sku_group, NULL AS store_name, l1_category, category, meta1, meta2, meta3, eoss, bf, ageing, inventory AS total_inventory, bad_inv, blocked_inv, inv_not_synced, stock_in_transfer, stock_not_found, open_sale, open_purchase, north_warehouse, south_warehouse, XS, S, M, L, XL, \"2XL\", \"3XL\", \"4XL\", \"5XL\", \"6XL\", \"7XL\", \"8XL\", full_size_options, CASE WHEN full_size_options >= 1 THEN \'full_size\' ELSE \'cut_size\' END AS size_flag, CASE WHEN sku_group LIKE \'%4MBG%\' THEN full_size_options * 10 ELSE full_size_options * 12 END AS full_size_inv, shopify_sales_qty, mp_sales_qty, offline_sales_qty, shopify_sales_value, mp_sales_value, offline_sales_value, ROUND(total_ros_l30, 2) AS ros_l30, ROUND(mp_ros_l30, 2) AS mp_ros_l30, ROUND(shopify_ros_l30, 2) AS shopify_ros_l30, ROUND(offline_ros_l30, 2) AS offline_ros_l30, \'Warehouse\' AS table_identifier FROM warehouse_calc UNION ALL SELECT sku_group, store_name, l1_category, category, meta1, meta2, meta3, eoss, bf, ageing, inventory AS total_inventory, NULL AS bad_inv, NULL AS blocked_inv, NULL AS inv_not_synced, NULL AS stock_in_transfer, NULL AS stock_not_found, NULL AS open_sale, NULL AS open_purchase, NULL AS north_warehouse, NULL AS south_warehouse, XS, S, M, L, XL, \"2XL\", \"3XL\", \"4XL\", \"5XL\", \"6XL\", \"7XL\", \"8XL\", full_size_options, CASE WHEN full_size_options >= 1 THEN \'full_size\' ELSE \'cut_size\' END AS size_flag, CASE WHEN sku_group LIKE \'%4MBG%\' THEN full_size_options * 10 ELSE full_size_options * 12 END AS full_size_inv, NULL AS shopify_sales_qty, NULL AS mp_sales_qty, sales AS offline_sales_qty, NULL AS shopify_sales_value, NULL AS mp_sales_value, price * sales AS offline_sales_value, ROUND(ros_l30, 2) AS ros_l30, ROUND(mp_ros_l30, 2) AS mp_ros_l30, ROUND(shopify_ros_l30, 2) AS shopify_ros_l30, ROUND(offline_ros_l30, 2) AS offline_ros_l30, \'Store\' AS table_identifier FROM store_final_calc ;",
                    "transaction": true
                }
            ) }}
